use verus::prelude::*;

#[requires(a.len() >= 1)]
#[ensures(result.len() == a.len() - 1)]
#[ensures(forall(|i: usize| i < result.len() ==> result[i] == a[i + 1]))]
#[decreases(a.len())]
fn remove_front(a: &Vec<i32>) -> Vec<i32> {
    // Since `a` is guaranteed to be non-empty, we can safely take the slice from index 1 onward.
    a[1..].to_vec()
}

